    "productDetails": "{\n  \"form\": \"Специализированный антивозрастной крем\",\n  \"size\": \"50г\",\n  \"target\": \"Антивозрастной уход за областью шеи и декольте\",\n  \"technology\": \"Продвинутый пептидный комплекс с витаминной смесью\",\n  \"keyBenefits\": \"Лифтинг, укрепление, депигментация, улучшение текстуры\",\n  \"usage\": \"Ежедневное антивозрастное лечение, утро и вечер\",\n  \"skinType\": \"Всех типов кожи, особенно стареющей области шеи и декольте\",\n  \"application\": \"Нанесите на чистую область шеи и декольте\",\n  \"testing\": \"Дерматологически протестировано и клинически доказано\",\n  \"origin\": \"Южная Корея\"\n}",
