    "productDetails": "{\n  \"form\": \"Мультивитаминный крем для сияния\",\n  \"size\": \"50г (Домашний уход) / 230г (Профессиональный)\",\n  \"target\": \"Антивозрастной уход и осветление кожи\",\n  \"technology\": \"Комплекс VITA 12 с астаксантином\",\n  \"keyBenefits\": \"Осветление, глубокое увлажнение, антиоксидантная защита\",\n  \"usage\": \"Утреннее и вечернее применение\",\n  \"skinType\": \"Всех типов кожи, особенно стареющей и тусклой\",\n  \"origin\": \"Южная Корея\"\n}",
    "benefits": "[\n  \"Осветление - помогает осветлить пигментные пятна и улучшить общий тон кожи\",\n  \"Глубокое увлажнение - обеспечивает интенсивную гидратацию, делая кожу мягкой и упругой\",\n  \"Антиоксидантная защита - защищает от свободных радикалов, уменьшая признаки старения\",\n  \"Питание кожи - поставляет необходимые питательные вещества для улучшения здоровья и внешнего вида кожи\",\n  \"Активация коллагена - стимулирует выработку коллагена для более упругой и молодой кожи\",\n  \"Дополнительная УФ-поддержка - астаксантин помогает при УФ-стрессе, но не заменяет SPF\"\n]",
    "ingredients": "[\n  {\n    \"name\": \"Астаксантин\",\n    \"description\": \"Мощный антиоксидант, который в 6,000 раз сильнее витамина C. Помогает уменьшить пигментацию кожи, вызванную свободными радикалами и воздействием солнца.\"\n  },\n  {\n    \"name\": \"Комплекс VITA 12\",\n    \"description\": \"Обеспечивает кожу питательными веществами, помогает увеличить выработку коллагена и предотвращает потерю влаги кожей.\"\n  },\n  {\n    \"name\": \"Глюконолактон\",\n    \"description\": \"Полигидроксикислота (PHA), которая улучшает тон кожи, отшелушивая омертвевшие клетки кожи и увлажняя кожу.\"\n  },\n  {\n    \"name\": \"Экстракт корня солодки уральской (Glycyrrhiza Uralensis)\",\n    \"description\": \"Ингибирует пигментацию, предотвращая активацию тирозиназы, осветляет кожу.\"\n  },\n  {\n    \"name\": \"Масло семян макадамии (Macadamia Ternifolia)\",\n    \"description\": \"Содержит линолевую кислоту, которая предотвращает трансэпидермальную потерю влаги и создает естественный защитный барьер.\"\n  },\n  {\n    \"name\": \"Аскорбиновая кислота (Витамин C)\",\n    \"description\": \"Природный антиоксидант, который защищает кожу от повреждений, вызванных УФ-излучением и свободными радикалами.\"\n  },\n  {\n    \"name\": \"Церамид NP\",\n    \"description\": \"Укрепляет естественный защитный липидный барьер кожи и улучшает долгосрочное увлажнение.\"\n  }\n]",
