    "productDetails": "{\n  \"form\": \"Многофункциональный крем против морщин\",\n  \"size\": \"50г (Домашний уход) / 250г (Профессиональный)\",\n  \"target\": \"Антивозрастной уход, уменьшение морщин и осветление\",\n  \"technology\": \"Бакучиол с прополисом, коллагеном и липосомой липидного барьера\",\n  \"keyBenefits\": \"Уменьшение морщин, укрепление, осветление, антиоксидантная защита\",\n  \"usage\": \"Утро и вечер — мягкий массаж\",\n  \"skinType\": \"Всех типов кожи, особенно зрелой\",\n  \"origin\": \"Южная Корея\"\n}",
