    "productDetails": "{\n  \"form\": \"Термочувствительные гидрогелевые патчи\",\n  \"size\": \"101г (60 патчей)\",\n  \"skinType\": \"Всех типов кожи, особенно зрелой и стареющей\",\n  \"technology\": \"Запатентованная технология термочувствительного гидрогеля\",\n  \"keyBenefits\": \"Уменьшение отечности, осветление темных кругов, разглаживание тонких линий\",\n  \"usage\": \"20-40 минут на одно применение\",\n  \"origin\": \"Южная Корея\"\n}",
