    "productDetails": "{\n  \"form\": \"Функциональный шампунь для кожи головы\",\n  \"size\": \"300мл\",\n  \"target\": \"Профилактика выпадения волос и здоровье кожи головы\",\n  \"technology\": \"Запатентованный комплекс ингредиентов с одобрением KFDA\",\n  \"keyBenefits\": \"Профилактика выпадения волос, охлаждение кожи головы, контроль кожного сала\",\n  \"usage\": \"Профессиональный и домашний уход\",\n  \"approval\": \"Одобренный KFDA функциональный продукт\",\n  \"origin\": \"Южная Корея\"\n}",
