    "ingredients": "[\n  {\n    \"name\": \"Ментол\",\n    \"description\": \"Охлаждающий компонент для кожи головы (1,12%), снижает ощущение жара и оставляет свежесть после очищения.\"\n  },\n  {\n    \"name\": \"Кофеин\",\n    \"description\": \"Стимулятор кожи головы (1%), поддерживает среду вокруг фолликулов и доставку питательных веществ.\"\n  },\n  {\n    \"name\": \"Copper Tripeptide-1\",\n    \"description\": \"Сигнальный пептид, поддерживающий синтез коллагена и укрепление среды кожи головы и волос.\"\n  },\n  {\n    \"name\": \"Биотин\",\n    \"description\": \"Витамин B7, поддерживающий структуру волос в составе функционального комплекса ухода за кожей головы.\"\n  },\n  {\n    \"name\": \"Пантенол (провитамин B5)\",\n    \"description\": \"Увлажняющий и кондиционирующий компонент, смягчающий кожу головы и волосы после мытья.\"\n  },\n  {\n    \"name\": \"Экстракт Viscum Album (омела)\",\n    \"description\": \"Патентованный растительный экстракт в составе CSS-комплекса для кондиционирования кожи головы и ухода при выпадении волос.\"\n  },\n  {\n    \"name\": \"Экстракт Saccharomyces Cerevisiae + солодовый экстракт\",\n    \"description\": \"Ферментный и солодовый экстракты, питающие среду кожи головы как часть запатентованного комплекса.\"\n  },\n  {\n    \"name\": \"Экстракт плодов Serenoa Serrulata (со пальметто)\",\n    \"description\": \"Ботанический ингредиент, традиционно используемый при истончении волос для поддержки среды фолликулов.\"\n  },\n  {\n    \"name\": \"Пироктон оламин\",\n    \"description\": \"Косметический биоцид, помогающий контролировать дисбаланс кожи головы, связанный с перхотью, во время очищения.\"\n  },\n  {\n    \"name\": \"Экстракты Acorus Calamus + Panax Ginseng + сои\",\n    \"description\": \"Растительное трио, кондиционирующее кожу головы и дополняющее охлаждающую очищающую основу шампуня.\"\n  },\n  {\n    \"name\": \"Full INCI\",\n    \"description\": \"Aqua (Water), Sodium C14-16 Olefin Sulfonate, Coco-Betaine, Glycerin, C12-13 Alketh-9, Menthol, Caffeine, Copper Tripeptide-1, Biotin, Panthenol, Viscum Album (Mistletoe) Extract, Saccharomyces Cerevisiae Extract, Malt Extract, Acorus Calamus Root Extract, Panax Ginseng Root Extract, Glycine Soja (Soybean) Seed Extract, Serenoa Serrulata Fruit Extract, Piroctone Olamine, Tocopherol, Citric Acid, Diospyros Kaki Fruit Extract, Camellia Japonica Leaf Extract, Ceratonia Siliqua (Carob) Fruit Extract, Lecithin, Menthyl Lactate, Ethylhexylglycerin, Glycine, Glyceryl Oleate, 1,2-Hexanediol, Glyceryl Stearate, Butylene Glycol, Coco-Glucoside, Sorbitol, Polyquaternium-67, Decyl Glucoside, Disodium EDTA, Acrylates Copolymer, Propanediol, Potassium Benzoate, Parfum (Fragrance).\"\n  }\n]",
    "howToUse": "[\n  {\n    \"step\": \"Смочите волосы\",\n    \"instruction\": \"Тщательно смочите волосы теплой водой\"\n  },\n  {\n    \"step\": \"Нанесите шампунь\",\n    \"instruction\": \"Возьмите необходимое количество и аккуратно помассируйте в кожу головы\"\n  },\n  {\n    \"step\": \"Массаж\",\n    \"instruction\": \"Используйте кончики пальцев для массажа кожи головы в течение 2-3 минут\"\n  },\n  {\n    \"step\": \"Смывание\",\n    \"instruction\": \"Тщательно смойте теплой водой\"\n  },\n  {\n    \"step\": \"Повторите при необходимости\",\n    \"instruction\": \"Для лучших результатов используйте дважды в неделю или как рекомендовано\"\n  },\n  {\n    \"step\": \"Последующие действия\",\n    \"instruction\": \"Используйте в сочетании с протоколом лечения HR³ MATRIX\"\n  }\n]",
